// The launcher's model: which cores this app was built with, whether the
// files each one needs are on the phone, the instances (separate save folders)
// each one has, and the folders a chosen core/instance runs with.
//
// No UI and no SDK dependencies here, so it can be tested on its own.

#pragma once

#include <cstdint>
#include <filesystem>
#include <optional>
#include <span>
#include <string>
#include <vector>

namespace mc360::launcher {

// One core built into the app. The table is generated by
// cmake/mc360_cores.cmake (see cores_table.cpp).
struct CoreInfo {
  const char* id;       // folder name under app/cores/, e.g. "tu9"
  const char* name;     // shown in the menu, e.g. "Title Update 9"
  const char* library;  // file name of the core library in Frameworks/
  // Read at build time from the default.xex/default.xexp codegen used. False
  // when they could not be read; the launcher then checks nothing.
  bool identity_known;
  uint32_t title_id;
  uint32_t media_id;      // of the disc default.xex
  uint32_t game_version;  // after the title update (or the disc's, without one)
  bool has_update;        // built with a default.xexp
  const char* update_dir;  // folder under Documents/ for the title update
  const char* save_dir;    // folder under Documents/ for instance 1
  const char* cache_dir;   // folder under Documents/ for the shader cache
};

std::span<const CoreInfo> BundledCores();

struct Issue {
  enum class Severity { kWarning, kError };
  Severity severity;
  std::string text;
};

struct Instance {
  int number = 1;  // 1-based
  std::filesystem::path user_data_root;
};

struct CoreStatus {
  const CoreInfo* core = nullptr;
  // The folder mounted as update:\, empty for none.
  std::filesystem::path update_root;
  std::vector<Issue> issues;
  // Always at least one.
  std::vector<Instance> instances;

  bool has_error() const;
  bool has_warning() const;
};

struct Selection {
  std::string core_id;
  int instance = 1;
  bool operator==(const Selection&) const = default;
};

struct LaunchPaths {
  std::filesystem::path update_data_root;
  std::filesystem::path user_data_root;
  std::filesystem::path cache_root;
};

class Launcher {
 public:
  // base_dir is the folder that holds game/ and the per-core folders: the
  // app's Documents folder on iOS.
  Launcher(std::filesystem::path base_dir, std::span<const CoreInfo> cores);

  // A title update folder set explicitly (update_data_root in mc360.toml).
  // Every core then uses it instead of looking for its own.
  void SetUpdateRootOverride(std::filesystem::path path) { update_root_override_ = std::move(path); }

  // Re-reads the folders. Call again after creating an instance.
  void Scan();

  // The disc files. Defaults to <base_dir>/game.
  void SetGameDir(std::filesystem::path path) { game_dir_ = std::move(path); }

  const std::filesystem::path& base_dir() const { return base_dir_; }
  std::filesystem::path game_dir() const { return game_dir_.empty() ? base_dir_ / "game" : game_dir_; }
  const std::vector<CoreStatus>& cores() const { return statuses_; }

  // Every core/instance pair, in menu order.
  std::vector<Selection> Options() const;
  const CoreStatus* FindCore(std::string_view id) const;

  // The menu is skipped when it has nothing to ask: one core, one instance and
  // nothing wrong with its files. `always` shows it regardless.
  bool ShouldShowMenu(bool always) const;
  // The option to start on: the last one used if it still exists, else the
  // first one without problems, else the first one.
  Selection DefaultSelection() const;

  // Creates the next instance folder for a core and returns its number.
  std::optional<int> CreateInstance(std::string_view core_id);

  std::optional<LaunchPaths> PathsFor(const Selection& selection) const;

  std::optional<Selection> LoadLastSelection() const;
  void SaveLastSelection(const Selection& selection) const;

  static std::filesystem::path InstanceFolder(const std::filesystem::path& base_dir,
                                              const CoreInfo& core, int instance);

 private:
  CoreStatus ScanCore(const CoreInfo& core) const;
  std::filesystem::path state_path() const { return base_dir_ / "launcher.toml"; }

  std::filesystem::path base_dir_;
  std::filesystem::path game_dir_;
  std::filesystem::path update_root_override_;
  std::span<const CoreInfo> core_infos_;
  std::vector<CoreStatus> statuses_;
};

}  // namespace mc360::launcher
